-- =============================================================================
-- AI Form Automation Agent — PostgreSQL schema (v1)
-- Target: PostgreSQL 16 (Azure Database for PostgreSQL Flexible Server)
-- Conventions:
--   * UUID v7-style ids generated by gen_random_uuid() (pgcrypto)
--   * All secrets / PII marked [ENC] are stored as AES-256-GCM envelopes
--     (bytea: version(1) | key_id(16) | iv(12) | tag(16) | ciphertext)
--     produced by the application layer — the DB never sees plaintext.
--   * Every tenant-owned table carries org_id and is protected by RLS.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS vector;      -- pgvector: field-label embeddings for learning

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
CREATE TYPE user_role          AS ENUM ('owner', 'admin', 'operator', 'reviewer', 'viewer');
CREATE TYPE proxy_type         AS ENUM ('http', 'https', 'socks5');
CREATE TYPE custom_field_type  AS ENUM ('text', 'date', 'number', 'email', 'phone', 'url', 'secret', 'file');
CREATE TYPE run_status         AS ENUM ('queued', 'launching', 'analysing', 'mapping', 'filling',
                                        'solving_captcha', 'awaiting_manual', 'awaiting_review',
                                        'submitting', 'succeeded', 'failed', 'cancelled', 'paused');
CREATE TYPE field_kind         AS ENUM ('text', 'email', 'tel', 'password', 'number', 'date', 'select',
                                        'checkbox', 'radio', 'file', 'textarea', 'hidden', 'combobox', 'unknown');
CREATE TYPE mapping_outcome    AS ENUM ('accepted', 'corrected', 'rejected', 'skipped', 'validation_failed');
CREATE TYPE captcha_kind       AS ENUM ('recaptcha_v2', 'recaptcha_v3', 'recaptcha_invisible', 'hcaptcha',
                                        'turnstile', 'slider', 'image');
CREATE TYPE captcha_result     AS ENUM ('solved', 'failed', 'timeout', 'rejected_by_site', 'escalated_manual');
CREATE TYPE provider_category  AS ENUM ('ai', 'captcha', 'browser', 'proxy', 'email');
CREATE TYPE provider_status    AS ENUM ('unknown', 'healthy', 'degraded', 'down');
CREATE TYPE audit_action       AS ENUM ('auth.login', 'auth.logout', 'auth.login_failed', 'auth.mfa',
                                        'profile.create', 'profile.update', 'profile.delete', 'profile.secret_read',
                                        'provider.create', 'provider.update', 'provider.rotate', 'provider.delete',
                                        'provider.test', 'run.create', 'run.approve', 'run.submit', 'run.cancel',
                                        'captcha.solve', 'user.invite', 'user.role_change', 'policy.update');

-- -----------------------------------------------------------------------------
-- Tenancy, users, authentication
-- -----------------------------------------------------------------------------
CREATE TABLE organizations (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name             text NOT NULL,
  slug             citext UNIQUE NOT NULL,
  plan             text NOT NULL DEFAULT 'starter',
  data_region      text NOT NULL DEFAULT 'uksouth',
  dek_wrapped      bytea NOT NULL,              -- per-org data key, wrapped by Azure Key Vault KEK
  dek_key_version  text NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email            citext UNIQUE NOT NULL,
  name             text,
  image_url        text,
  password_hash    text,                        -- argon2id; null for OAuth-only users
  email_verified   timestamptz,
  mfa_secret_enc   bytea,                       -- [ENC] TOTP secret
  mfa_enabled      boolean NOT NULL DEFAULT false,
  is_disabled      boolean NOT NULL DEFAULT false,
  last_login_at    timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE memberships (
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role             user_role NOT NULL DEFAULT 'operator',
  created_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, user_id)
);

-- Auth.js (next-auth) adapter tables
CREATE TABLE accounts (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id             uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type                text NOT NULL,
  provider            text NOT NULL,
  provider_account_id text NOT NULL,
  refresh_token       text,
  access_token        text,
  expires_at          bigint,
  token_type          text,
  scope               text,
  id_token            text,
  session_state       text,
  UNIQUE (provider, provider_account_id)
);

CREATE TABLE sessions (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_token    text UNIQUE NOT NULL,
  user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires          timestamptz NOT NULL,
  ip_address       inet,
  user_agent       text,
  created_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE verification_tokens (
  identifier       text NOT NULL,
  token            text NOT NULL,
  expires          timestamptz NOT NULL,
  PRIMARY KEY (identifier, token)
);

-- API-side refresh tokens (rotating, reuse-detected)
CREATE TABLE refresh_tokens (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  family_id        uuid NOT NULL,
  token_hash       bytea NOT NULL UNIQUE,       -- sha256(token)
  expires_at       timestamptz NOT NULL,
  revoked_at       timestamptz,
  replaced_by      uuid REFERENCES refresh_tokens(id),
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON refresh_tokens (user_id, family_id);

-- -----------------------------------------------------------------------------
-- Profiles (the reusable identity data)
-- -----------------------------------------------------------------------------
CREATE TABLE profiles (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  owner_user_id    uuid NOT NULL REFERENCES users(id),
  label            text NOT NULL,               -- "Profile A – John Smith"
  first_name_enc   bytea,                       -- [ENC]
  last_name_enc    bytea,                       -- [ENC]
  email_enc        bytea,                       -- [ENC]
  phone_enc        bytea,                       -- [ENC]
  email_blind_idx  bytea,                       -- HMAC-SHA256(email) for lookup without decrypting
  locale           text NOT NULL DEFAULT 'en-GB',
  timezone         text NOT NULL DEFAULT 'Europe/London',
  is_default       boolean NOT NULL DEFAULT false,
  version          integer NOT NULL DEFAULT 1,  -- optimistic locking
  deleted_at       timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON profiles (org_id) WHERE deleted_at IS NULL;

CREATE TABLE profile_addresses (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id       uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  kind             text NOT NULL DEFAULT 'primary',   -- primary | billing | shipping | registered_office
  line1_enc        bytea,                              -- [ENC]
  line2_enc        bytea,                              -- [ENC]
  city_enc         bytea,                              -- [ENC]
  region_enc       bytea,                              -- [ENC] County / State
  postcode_enc     bytea,                              -- [ENC]
  country_code     char(2) NOT NULL,                   -- ISO-3166 alpha-2 (not sensitive)
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (profile_id, kind)
);

-- Exactly ONE proxy per profile (UNIQUE profile_id). The profile's browser always egresses through it.
CREATE TABLE profile_proxies (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id           uuid NOT NULL UNIQUE REFERENCES profiles(id) ON DELETE CASCADE,
  org_id               uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  type                 proxy_type NOT NULL,
  host                 text NOT NULL,
  port                 integer NOT NULL CHECK (port BETWEEN 1 AND 65535),
  username_enc         bytea,                          -- [ENC]
  password_enc         bytea,                          -- [ENC]
  -- "Rotation settings" = credential rotation + health, never IP hopping between proxies
  credential_rotate_days integer CHECK (credential_rotate_days BETWEEN 1 AND 365),
  credentials_rotated_at timestamptz,
  sticky_session_id    text,                           -- provider sticky-session token so the IP stays constant
  health_status        provider_status NOT NULL DEFAULT 'unknown',
  last_checked_at      timestamptz,
  last_exit_ip         inet,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE profile_custom_fields (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  profile_id       uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  key              text NOT NULL,                      -- machine key, e.g. date_of_birth
  label            text NOT NULL,                      -- "Date of Birth"
  type             custom_field_type NOT NULL DEFAULT 'text',
  value_enc        bytea,                              -- [ENC] (null for type=file)
  blob_path        text,                               -- Azure Blob path for type=file (encrypted container)
  synonyms         text[] NOT NULL DEFAULT '{}',       -- user hints: {"DOB","Birthday"}
  sort_order       integer NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (profile_id, key)
);

-- Persistent browser identity per profile (cookies, localStorage, stable UA/viewport)
CREATE TABLE browser_profiles (
  profile_id         uuid PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE,
  org_id             uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  storage_blob_path  text,                             -- encrypted Playwright storageState / userDataDir tarball
  user_agent         text NOT NULL,                    -- fixed for the life of the profile
  viewport_w         integer NOT NULL DEFAULT 1440,
  viewport_h         integer NOT NULL DEFAULT 900,
  locale             text NOT NULL DEFAULT 'en-GB',
  timezone           text NOT NULL DEFAULT 'Europe/London',
  updated_at         timestamptz NOT NULL DEFAULT now()
);

-- Accounts the agent created/used on third-party sites for a profile (1 per domain per profile)
CREATE TABLE site_accounts (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  profile_id       uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  domain           citext NOT NULL,
  username_enc     bytea,                              -- [ENC]
  password_enc     bytea,                              -- [ENC] generated strong password
  created_by_run   uuid,
  verified_at      timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (profile_id, domain)                          -- guardrail: one account per site per profile
);

-- -----------------------------------------------------------------------------
-- Organisation policy (guardrails)
-- -----------------------------------------------------------------------------
CREATE TABLE org_policies (
  org_id                     uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE,
  require_review_before_submit boolean NOT NULL DEFAULT true,  -- COMMIT actions always need approval
  require_review_every_step  boolean NOT NULL DEFAULT false, -- also stop on Next/Continue steps
  captcha_solving_enabled    boolean NOT NULL DEFAULT false,
  captcha_max_spend_daily_usd numeric(10,2) NOT NULL DEFAULT 5.00,
  max_runs_per_domain_per_day integer NOT NULL DEFAULT 20,
  max_concurrent_runs        integer NOT NULL DEFAULT 3,
  ai_provider_order          text[] NOT NULL DEFAULT '{claude,openai,gemini}',
  captcha_provider_order     text[] NOT NULL DEFAULT '{2captcha,capsolver,anticaptcha,capmonster,deathbycaptcha,bestcaptchasolver,dispurcaptcha,resolvr,compatible}',
  auto_accept_confidence     numeric(4,3) NOT NULL DEFAULT 0.920,
  updated_at                 timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE domain_rules (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid REFERENCES organizations(id) ON DELETE CASCADE,  -- NULL = platform-wide rule
  domain           citext NOT NULL,
  rule             text NOT NULL CHECK (rule IN ('allow', 'block')),
  reason           text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE NULLS NOT DISTINCT (org_id, domain)
);

-- -----------------------------------------------------------------------------
-- Provider credentials (AI, CAPTCHA, browser, proxy, email) — encrypted at rest
-- -----------------------------------------------------------------------------
CREATE TABLE provider_credentials (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  category         provider_category NOT NULL,
  provider         text NOT NULL,          -- claude|openai|gemini|2captcha|anticaptcha|capmonster|deathbycaptcha|
                                           -- bestcaptchasolver|capsolver|dispurcaptcha|resolvr|compatible|browserless|browserbase|brightdata|oxylabs|smartproxy|
                                           -- m365|smtp|sendgrid
  label            text NOT NULL DEFAULT 'primary',
  secret_enc       bytea NOT NULL,         -- [ENC] JSON {apiKey, ...}
  secret_last4     text NOT NULL,          -- shown in UI as •••• last4
  config           jsonb NOT NULL DEFAULT '{}',  -- non-secret: model, endpoint, region
  priority         integer NOT NULL DEFAULT 100, -- lower = tried first (failover order)
  is_active        boolean NOT NULL DEFAULT true,
  status           provider_status NOT NULL DEFAULT 'unknown',
  last_tested_at   timestamptz,
  last_test_error  text,
  rotated_at       timestamptz,
  previous_secret_enc bytea,               -- kept for grace period during rotation
  previous_expires_at timestamptz,
  created_by       uuid REFERENCES users(id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (org_id, provider, label)
);
CREATE INDEX ON provider_credentials (org_id, category, priority) WHERE is_active;

-- -----------------------------------------------------------------------------
-- Automation runs
-- -----------------------------------------------------------------------------
CREATE TABLE automation_runs (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  profile_id       uuid NOT NULL REFERENCES profiles(id),
  created_by       uuid NOT NULL REFERENCES users(id),
  approved_by      uuid REFERENCES users(id),
  url              text NOT NULL,
  domain           citext NOT NULL,
  intent           text NOT NULL DEFAULT 'auto',   -- auto|signup|login|application|contact|onboarding
  status           run_status NOT NULL DEFAULT 'queued',
  current_step     integer NOT NULL DEFAULT 0,
  total_steps      integer,
  completion_confidence numeric(4,3),
  fields_total     integer NOT NULL DEFAULT 0,
  fields_filled    integer NOT NULL DEFAULT 0,
  fields_corrected integer NOT NULL DEFAULT 0,
  ai_provider_used text,
  ai_tokens_in     integer NOT NULL DEFAULT 0,
  ai_tokens_out    integer NOT NULL DEFAULT 0,
  ai_cost_usd      numeric(10,5) NOT NULL DEFAULT 0,
  captcha_cost_usd numeric(10,5) NOT NULL DEFAULT 0,
  checkpoint       jsonb,                          -- resumable state: step, url, filled values hash, storageState ref
  error_code       text,
  error_message    text,
  started_at       timestamptz,
  review_ready_at  timestamptz,
  submitted_at     timestamptz,
  finished_at      timestamptz,
  duration_ms      integer GENERATED ALWAYS AS
                   ((EXTRACT(EPOCH FROM (finished_at - started_at)) * 1000)::integer) STORED,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON automation_runs (org_id, created_at DESC);
CREATE INDEX ON automation_runs (org_id, status);
CREATE INDEX ON automation_runs (org_id, domain, created_at DESC);

CREATE TABLE run_steps (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id           uuid NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE,
  org_id           uuid NOT NULL,
  step_index       integer NOT NULL,
  page_url         text NOT NULL,
  page_title       text,
  page_kind        text,                           -- signup|login|form|verification|confirmation|unknown
  screenshot_path  text,                           -- blob path (PII-redacted copy for review)
  dom_snapshot_path text,
  started_at       timestamptz NOT NULL DEFAULT now(),
  finished_at      timestamptz,
  UNIQUE (run_id, step_index)
);

CREATE TABLE run_events (                          -- live activity stream (also published via Redis pub/sub)
  id               bigserial PRIMARY KEY,
  run_id           uuid NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE,
  org_id           uuid NOT NULL,
  level            text NOT NULL DEFAULT 'info',
  type             text NOT NULL,                  -- status|field_filled|captcha|navigation|error|note
  message          text NOT NULL,
  data             jsonb,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON run_events (run_id, id);

-- -----------------------------------------------------------------------------
-- Detected fields + AI decisions (the learning substrate)
-- -----------------------------------------------------------------------------
CREATE TABLE detected_fields (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id           uuid NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE,
  step_id          uuid NOT NULL REFERENCES run_steps(id) ON DELETE CASCADE,
  org_id           uuid NOT NULL,
  field_key        text NOT NULL,                  -- stable hash of (domain, form signature, locator)
  locator          text NOT NULL,                  -- Playwright locator string
  kind             field_kind NOT NULL,
  label            text,
  name_attr        text,
  id_attr          text,
  placeholder      text,
  autocomplete     text,
  aria_label       text,
  nearby_text      text,
  options          jsonb,                          -- select/radio options [{value,label}]
  required         boolean NOT NULL DEFAULT false,
  frame_path       text,                           -- iframe chain for embedded forms
  in_shadow_dom    boolean NOT NULL DEFAULT false,
  visible          boolean NOT NULL DEFAULT true
);
CREATE INDEX ON detected_fields (run_id);

CREATE TABLE ai_decisions (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL,
  run_id           uuid NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE,
  field_id         uuid NOT NULL REFERENCES detected_fields(id) ON DELETE CASCADE,
  source           text NOT NULL,                  -- memory|heuristic|llm
  provider         text,                           -- claude|openai|gemini
  model            text,
  profile_path     text,                           -- e.g. personal.firstName / address.primary.postcode / custom.date_of_birth / generated.password
  transform        text,                           -- e.g. date:DD/MM/YYYY, phone:e164, split:first
  proposed_value_hash bytea,                       -- sha256 — never store the PII value itself
  confidence       numeric(4,3) NOT NULL,
  reasoning        text NOT NULL,
  final_profile_path text,                         -- after user review
  outcome          mapping_outcome,
  latency_ms       integer,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON ai_decisions (org_id, created_at DESC);
CREATE INDEX ON ai_decisions (run_id);

CREATE TABLE user_corrections (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL,
  decision_id      uuid NOT NULL REFERENCES ai_decisions(id) ON DELETE CASCADE,
  user_id          uuid NOT NULL REFERENCES users(id),
  from_profile_path text,
  to_profile_path  text,
  from_transform   text,
  to_transform     text,
  note             text,
  created_at       timestamptz NOT NULL DEFAULT now()
);

-- Learned mapping memory: (domain-specific) + (global semantic) knowledge
CREATE TABLE mapping_memory (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid REFERENCES organizations(id) ON DELETE CASCADE, -- NULL = global (anonymised, opt-in)
  scope            text NOT NULL CHECK (scope IN ('domain', 'global')),
  domain           citext,                         -- required when scope=domain
  field_key        text,                           -- exact field match when scope=domain
  signature_text   text NOT NULL,                  -- normalised "label | name | placeholder | autocomplete"
  embedding        vector(1536),                   -- semantic similarity lookup
  profile_path     text NOT NULL,
  transform        text,
  successes        integer NOT NULL DEFAULT 0,
  failures         integer NOT NULL DEFAULT 0,
  corrections      integer NOT NULL DEFAULT 0,
  -- Beta(α,β) posterior mean, used as calibrated prior confidence
  alpha            numeric NOT NULL DEFAULT 1,
  beta             numeric NOT NULL DEFAULT 1,
  last_used_at     timestamptz NOT NULL DEFAULT now(),
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX mapping_memory_domain_uq ON mapping_memory (org_id, domain, field_key, profile_path)
  WHERE scope = 'domain';
CREATE INDEX mapping_memory_embedding_idx ON mapping_memory USING hnsw (embedding vector_cosine_ops);

-- Per-site playbooks: learned navigation for multi-step flows (button to click, step order)
CREATE TABLE site_playbooks (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid REFERENCES organizations(id) ON DELETE CASCADE,
  domain           citext NOT NULL,
  flow             text NOT NULL,                  -- signup|login|application
  steps            jsonb NOT NULL,                 -- [{urlPattern, formSignature, nextAction:{locator}}]
  success_count    integer NOT NULL DEFAULT 0,
  failure_count    integer NOT NULL DEFAULT 0,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  UNIQUE (org_id, domain, flow)
);

-- Confidence calibration buckets (reliability diagram data)
CREATE TABLE confidence_calibration (
  org_id           uuid NOT NULL,
  bucket           numeric(3,2) NOT NULL,          -- 0.50, 0.55 … 0.95
  predictions      integer NOT NULL DEFAULT 0,
  correct          integer NOT NULL DEFAULT 0,
  updated_at       timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, bucket)
);

-- -----------------------------------------------------------------------------
-- CAPTCHA analytics
-- -----------------------------------------------------------------------------
CREATE TABLE captcha_events (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL,
  run_id           uuid NOT NULL REFERENCES automation_runs(id) ON DELETE CASCADE,
  kind             captcha_kind NOT NULL,
  domain           citext NOT NULL,
  provider         text,                           -- null when escalated straight to manual
  attempt          integer NOT NULL DEFAULT 1,
  result           captcha_result NOT NULL,
  provider_task_id text,
  solve_ms         integer,
  cost_usd         numeric(10,5) NOT NULL DEFAULT 0,
  error            text,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON captcha_events (org_id, created_at DESC);
CREATE INDEX ON captcha_events (org_id, provider, kind);

CREATE MATERIALIZED VIEW captcha_provider_stats AS
SELECT org_id, provider, kind,
       count(*)                                         AS attempts,
       count(*) FILTER (WHERE result = 'solved')        AS solved,
       count(*) FILTER (WHERE result <> 'solved')       AS failed,
       round(100.0 * count(*) FILTER (WHERE result = 'solved') / NULLIF(count(*),0), 2) AS success_rate_pct,
       round(avg(solve_ms) FILTER (WHERE result = 'solved'))   AS avg_solve_ms,
       round(avg(cost_usd) FILTER (WHERE result = 'solved'), 5) AS cost_per_solve_usd,
       sum(cost_usd)                                    AS total_cost_usd
FROM captcha_events
WHERE provider IS NOT NULL AND created_at > now() - interval '30 days'
GROUP BY org_id, provider, kind;
CREATE UNIQUE INDEX ON captcha_provider_stats (org_id, provider, kind);

-- -----------------------------------------------------------------------------
-- Provider usage (AI + others) for cost dashboards
-- -----------------------------------------------------------------------------
CREATE TABLE provider_usage (
  id               bigserial PRIMARY KEY,
  org_id           uuid NOT NULL,
  provider         text NOT NULL,
  category         provider_category NOT NULL,
  run_id           uuid REFERENCES automation_runs(id) ON DELETE SET NULL,
  operation        text NOT NULL,                  -- map_fields|classify_page|solve_captcha|embed
  success          boolean NOT NULL,
  failover_from    text,
  latency_ms       integer,
  units_in         integer,
  units_out        integer,
  cost_usd         numeric(10,5) NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON provider_usage (org_id, created_at DESC);

-- -----------------------------------------------------------------------------
-- Uploaded documents usable for file-upload fields
-- -----------------------------------------------------------------------------
CREATE TABLE documents (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id           uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  profile_id       uuid REFERENCES profiles(id) ON DELETE CASCADE,
  kind             text NOT NULL,                  -- cv|id_document|proof_of_address|logo|certificate|other
  filename         text NOT NULL,
  mime_type        text NOT NULL,
  size_bytes       bigint NOT NULL,
  blob_path        text NOT NULL,
  sha256           bytea NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now()
);

-- -----------------------------------------------------------------------------
-- Audit log — append-only, hash-chained for tamper evidence
-- -----------------------------------------------------------------------------
CREATE TABLE audit_logs (
  id               bigserial PRIMARY KEY,
  org_id           uuid,
  actor_user_id    uuid,
  actor_ip         inet,
  actor_ua         text,
  action           audit_action NOT NULL,
  target_type      text,
  target_id        text,
  metadata         jsonb NOT NULL DEFAULT '{}',    -- never contains secrets/PII values; diffs list field names only
  prev_hash        bytea,
  row_hash         bytea NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ON audit_logs (org_id, created_at DESC);
CREATE INDEX ON audit_logs (org_id, action, created_at DESC);

CREATE OR REPLACE FUNCTION audit_logs_chain() RETURNS trigger AS $$
DECLARE last_hash bytea;
BEGIN
  -- Serialise appends per org with a transaction-scoped advisory lock (the app role has no UPDATE
  -- privilege on audit_logs, so row locks via FOR UPDATE are not available — by design).
  PERFORM pg_advisory_xact_lock(hashtext('audit:' || coalesce(NEW.org_id::text, 'platform')));
  SELECT row_hash INTO last_hash FROM audit_logs
   WHERE org_id IS NOT DISTINCT FROM NEW.org_id ORDER BY id DESC LIMIT 1;
  NEW.prev_hash := last_hash;
  NEW.row_hash := digest(
     coalesce(encode(last_hash,'hex'),'') || NEW.action::text || coalesce(NEW.actor_user_id::text,'') ||
     coalesce(NEW.target_type,'') || coalesce(NEW.target_id,'') || NEW.metadata::text || NEW.created_at::text,
     'sha256');
  RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_logs_chain_trg BEFORE INSERT ON audit_logs FOR EACH ROW EXECUTE FUNCTION audit_logs_chain();

CREATE OR REPLACE FUNCTION forbid_mutation() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'audit_logs is append-only'; END $$ LANGUAGE plpgsql;
CREATE TRIGGER audit_logs_no_update BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- -----------------------------------------------------------------------------
-- updated_at maintenance
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN NEW.updated_at := now(); RETURN NEW; END $$ LANGUAGE plpgsql;

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['organizations','users','profiles','profile_addresses','profile_proxies',
                           'profile_custom_fields','provider_credentials','org_policies'] LOOP
    EXECUTE format('CREATE TRIGGER %I_touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()', t, t);
  END LOOP;
END $$;

-- -----------------------------------------------------------------------------
-- Row-level security: the API sets `SET LOCAL app.org_id = '<uuid>'` per transaction
-- -----------------------------------------------------------------------------
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['profiles','profile_addresses','profile_proxies','profile_custom_fields',
                           'browser_profiles','site_accounts','provider_credentials','automation_runs',
                           'run_steps','run_events','detected_fields','ai_decisions','user_corrections',
                           'captcha_events','provider_usage','documents'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY tenant_isolation ON %I
                    USING (org_id = current_setting('app.org_id', true)::uuid)
                    WITH CHECK (org_id = current_setting('app.org_id', true)::uuid)$p$, t);
  END LOOP;
END $$;

-- Application role (no BYPASSRLS, no DDL)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'formagent_app') THEN
    CREATE ROLE formagent_app LOGIN;
  END IF;
END $$;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO formagent_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO formagent_app;
REVOKE UPDATE, DELETE ON audit_logs FROM formagent_app;

-- -----------------------------------------------------------------------------
-- Dashboard views
-- -----------------------------------------------------------------------------
CREATE VIEW v_dashboard_kpis AS
SELECT r.org_id,
       count(*)                                              AS total_runs,
       count(*) FILTER (WHERE status = 'succeeded')          AS successful_runs,
       count(*) FILTER (WHERE status = 'failed')             AS failed_runs,
       count(*) FILTER (WHERE status IN ('launching','analysing','mapping','filling','solving_captcha',
                                         'awaiting_manual','awaiting_review','submitting')) AS active_sessions,
       round(avg(completion_confidence)::numeric, 3)          AS avg_confidence,
       round(avg(duration_ms) FILTER (WHERE status='succeeded'))  AS avg_duration_ms,
       round(100.0 * (1 - sum(fields_corrected)::numeric / NULLIF(sum(fields_filled),0)), 2) AS ai_accuracy_pct
FROM automation_runs r
WHERE r.created_at > now() - interval '30 days'
GROUP BY r.org_id;

CREATE VIEW v_learning_trend AS
SELECT org_id, date_trunc('week', created_at) AS week,
       count(*) AS decisions,
       round(100.0 * count(*) FILTER (WHERE outcome = 'accepted') / NULLIF(count(*) FILTER (WHERE outcome IS NOT NULL),0), 2) AS acceptance_pct,
       round(100.0 * count(*) FILTER (WHERE source = 'memory') / NULLIF(count(*),0), 2) AS memory_hit_pct
FROM ai_decisions GROUP BY org_id, date_trunc('week', created_at);
